package android.graphics.drawable;import android.graphics.Bitmap;public class BitmapDrawable extends Drawable{private final Bitmap bitmap;public BitmapDrawable(Object ignored,Bitmap bitmap){this.bitmap=bitmap;}public Bitmap getBitmap(){return bitmap;}@Override public int getIntrinsicWidth(){return bitmap.getWidth();}@Override public int getIntrinsicHeight(){return bitmap.getHeight();}}
